/*  @title  Microwave space run remix
    @by pRIV
*/

samples('shabda:Drop-the-soap')
setcpm(120/4)

var voice = s("micro-narration:1").legato(1).slow(4).crush(8).room(1) 

var drum = stack(sound("bd!4"),
            sound("[rim hh]!4"))   

var drum2 = note("[-- f2]").sound("square").slow(2).fm(4).fmh(2.23).lpf(200).freq(50) 

var count1 = note("[bb3 c4 dd3 c4]*2 [c4 bb3 db3 c4]*2[bb3 c4 dd3 c4]*2 [c4 bb3 db3 c4]*2").slow(4).sound("z_triangle")

var des = note("f3 db3 c3 f2").sound("square").crush(5).lfo({c:s}).room(0.5).lfo().slow(2) 

var open = note("f3").sound("square").crush(5).lfo({c:s}).room(0.5).lfo().penv("12").legato(0.2).fast(4) 

var fastharp = note("bb2 f3 c4 f3 c4 db4 c4 ab3 db2 c4 db4 ab4 db4 ab4 db4 db2")
  .sound("sawtooth")
  .someCycles(x=>x.legato("0.4")).lpf(sine.range(200, 2000)).room(saw.range(0.2,2)) 


var harpca =  stack(note("bb2 f3 c4 f3 c4 db4 c4 ab3 db2 c4 db4 ab4 db4 ab4 db4 db2").sound("<square casio>").someCycles(x=>x.palindrome()) 
  ,note("bb3 f4 c6 f4 c5 db5 c4 ab3 db2 c4 db4 ab4 db4 ab4 db4 db2").sound("<square casio>").someCycles(x=>x.palindrome())
  .fm("4 8 16 18").fmh("<1.5 2.5 3.5>").lpf(600) )

var mainhi = note("[db4 f4 c5 db5]*2 [f4 ab4 ab3 f3]*2[db5 c5 db5 ab5]*2 [ab5 f5 db5 f4]*2")
  .sound("square").slow(4).someCyclesBy(0.3, x=>x.rev())

var raiso = note("bb2 f3 c4 f3 c4 db4 c4 ab3 db2 c4 db4 ab4 db4 ab4 db4 db2")
  .sound("sawtooth").slow(2).clip("0.5").decay(0.3).room(0.8).lpf(1200).fm(8).someCycles(x=>x.palindrome()).almostNever(x=>x.legato("0.2"))

var fastharp2 = note("bb4 f5 c6 f4 c5 db5 c6 ab4 db3 c6 db5 ab6 db6 ab5 db5 db3").sound("square").tremolosync("4").tremoloskew("<1 .5 0>")

var drop = sound("micro-narration:3").slow(2)

arrange(
  [4,stack(voice,open)],
  [2,stack(drum,open,des)],
  [2,stack(drum,des)],
  [2, stack(drum, des, drum2)],
  [4, stack(drum, des, drum2, fastharp)],
  [2, stack(drum, des, drum2, fastharp.slow(1)).lpf(sine.range(500, 2000)).room(saw.range(0.5,2)) ],
  [2, stack(drum, des, drum2, fastharp.slow(1)).lpf(sine.range(800, 2000)).room(saw.range(0.8,2)),fastharp2],
  [1, drop],
  [1, drum],
  [4, stack(drum, des, drum2, fastharp,harpca)],
  [4, stack(drum, des, drum2, fastharp,harpca.lpf(200),mainhi)],
  [4, stack(drum, des, drum2, fastharp,harpca.lpf(200),mainhi.rev())],
  [4, stack(drum, des, drum2, fastharp.lpf(200),harpca,mainhi.palindrome())],
  [2, stack(drum, des, drum2, fastharp,harpca,count1)],
  [2, stack(drum, des.lpf(400), drum2, fastharp,harpca,count1)],
  [2, stack(drum, des.lpf(400), drum2,fastharp,harpca,raiso,count1,fastharp2)],
  //[2, stack(drum, des.lpf(400), drum2,raiso,count1,mainhi)],
  //[2, stack(drum, des, drum2, fastharp,harpca.lpf(200),mainhi.rev())],
  //[2, stack(drum, des.lpf(400), drum2,raiso,count1)],
  //[4, stack(drum, des.lpf(400), drum2,fastharp,fastharp2,harpca,count1,raiso)],
  [2, stack(drum, des.lpf(400), fastharp,drum2,count1,raiso,fastharp2)],
  [2, stack(drum, des.lpf(400), fastharp,drum2,raiso)],
  [2, stack(drum, des.lpf(400), fastharp,drum2)],
  [4, stack(drum, des.lpf(400),drum2,voice)],
  [1, drop],
  [1, "---"],


)
